(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["clinical-medicine-and-surgery-i-exam-4"]={"title":"Clinical Medicine and Surgery I Exam 4","sections":[{"id":"def","title":"Definitions & Classification","style":"--acc:#702d7a;--acc-bg:#ebe2ec;--acc-zebra:#f5f0f6;--acc-ink:#57235f"},{"id":"secondary","title":"Secondary Causes","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"organ","title":"Target Organ Damage","style":"--acc:#a3341f;--acc-bg:#f2e3e0;--acc-zebra:#f9f1ef;--acc-ink:#7f2918"},{"id":"assess","title":"Assessment","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"treat","title":"Treatment","style":"--acc:#1f5c3a;--acc-bg:#e0e8e3;--acc-zebra:#eff4f1;--acc-ink:#18482d"},{"id":"resist","title":"Resistance & Emergency","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"l21-hypo","title":"Hypotension: Definitions & Types","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l21-orth","title":"Orthostatic & Reflex Syncope","style":"--acc:#7a2d5c;--acc-bg:#ece2e8;--acc-zebra:#f6f0f4;--acc-ink:#5f2348"},{"id":"l21-pots","title":"Postural Tachycardia, Cardiogenic & Drugs","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l22-lipo","title":"Lipids: Garbage System & Lipoproteins","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l22-disorders","title":"Lipids: Disorders & Screening","style":"--acc:#a3341f;--acc-bg:#f2e3e0;--acc-zebra:#f9f1ef;--acc-ink:#7f2918"},{"id":"l22-tx","title":"Lipids: Drugs & 2018 Statin Decisions","style":"--acc:#1f5c3a;--acc-bg:#e0e8e3;--acc-zebra:#eff4f1;--acc-ink:#18482d"},{"id":"l23-murmurs","title":"Valves: Murmur Words & Test Tips","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l23-left","title":"Valves: Aortic & Mitral","style":"--acc:#7a2d5c;--acc-bg:#ece2e8;--acc-zebra:#f6f0f4;--acc-ink:#5f2348"},{"id":"l23-right","title":"Valves: Right Side & Prosthetic Valves","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l25-core","title":"Heart Failure: Groups, Stages & Classes","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"l25-dx","title":"Heart Failure: Diagnosis & Therapy","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"}],"rows":[{"t":"Treatment goal","d":"<b>Below 130/80</b>, with values closer to 120/80 encouraged where appropriate. The same number defines the condition and measures control.","s":0},{"t":"Primary (essential)","d":"No single identifiable underlying cause. <b>The vast majority of adult cases.</b>","s":0},{"t":"Secondary","d":"An identifiable underlying condition drives the pressure. Go looking when the <i>pattern</i> is wrong (see next topic).","s":0},{"t":"Resistant","d":"Above goal despite <b>three complementary drugs at maximally tolerated doses</b>.","s":0},{"t":"Hypertensive emergency","d":"Severe elevation <b>with acute hypertension-mediated organ injury</b>. <b>No numeric cutoff exists</b> &mdash; 230/130 with no acute organ involvement is severe <i>asymptomatic</i> hypertension. Qualifying injury: encephalopathy, acute pulmonary edema, acute kidney injury, aortic dissection, acute coronary syndrome.","s":0},{"t":"White coat vs masked","d":"<b>White coat</b> = high office, normal out-of-office. <b>Masked</b> = normal office, high out-of-office &mdash; and it carries <b>real cardiovascular risk</b>, which is why out-of-office measurement is not only about avoiding overtreatment.","s":0},{"t":"Epidemiology","d":"Roughly <b>one in five</b> of those affected are controlled to goal nationally. <b>Prevalence rises sharply with age</b>: 23.4% at 18&ndash;39 years, 52.5% at 40&ndash;59 and 71.6% at 60 and over.","s":0},{"t":"Risk factors (primary)","d":"Advancing age &middot; family history &middot; excess adiposity &middot; high dietary sodium &middot; inactivity &middot; excess alcohol &middot; dyslipidemia &middot; insulin resistance. Low potassium intake and poor sleep are modifiable too.","s":0},{"t":"When to go looking","d":"<b>Early onset &middot; abrupt new onset &middot; resistance &middot; sudden loss of previously stable control.</b> The pattern is the clue, not any single reading.","s":1},{"t":"Chronic kidney disease","d":"Impaired sodium excretion expands extracellular volume, with renin-angiotensin-aldosterone and sympathetic activation. Needs an abnormality persisting <b>&ge; 3 months</b>. Relationship is <b>bidirectional</b> &mdash; evaluate diabetes rather than assuming which came first.","s":1},{"t":"Renovascular disease","d":"Atherosclerotic (older, vascular, often bilateral and progressive) or fibromuscular dysplasia (young). Clues: resistant or abrupt elevation &middot; <b>abdominal bruit</b> &middot; <b>asymmetric kidneys</b> &middot; recurrent <b>flash pulmonary edema</b> &middot; <b>marked creatinine rise after starting an ACE inhibitor</b>. Refer early for flash edema, progressive renal decline despite optimal therapy, or truly refractory control.","s":1},{"t":"Primary aldosteronism","d":"<b>Autonomous aldosterone production independent of renin.</b> Screen for resistant pressure, <b>unexplained hypokalemia</b>, adrenal incidentaloma, early or familial hypertension. Test: <b>morning aldosterone to renin ratio</b>, positive above roughly <b>20:1</b> with an adequate aldosterone concentration.","s":1},{"t":"Obstructive sleep apnea","d":"Recurrent airway obstruction &rarr; intermittent hypoxemia and arousal &rarr; <b>sustained sympathetic activation</b>. Snoring, witnessed apneas, daytime sleepiness. Confirm with <b>polysomnography or validated home testing</b>.","s":1},{"t":"Drugs & substances","d":"Ask beyond the prescription list: <b>over-the-counter drugs, recreational substances, licorice, herbal supplements</b>. Excess alcohol raises pressure chronically, and <b>withdrawal can raise it acutely</b>.","s":1},{"t":"Thyroid","d":"<b>Hyper</b> &rarr; raises cardiac output &rarr; <b>systolic</b> elevation. <b>Hypo</b> &rarr; raises vascular resistance &rarr; <b>diastolic</b> elevation.","s":1},{"t":"Cushing syndrome","d":"Glucocorticoid excess. Proximal muscle weakness &middot; easy bruising &middot; thin skin &middot; broad purple striae &middot; central adiposity. Test: low-dose dexamethasone suppression.","s":1},{"t":"Pheochromocytoma","d":"Catecholamine excess. The <b>five Ps</b>: pressure, perspiration, palpitations, pallor, tremor &mdash; <b>paroxysmal, with well intervals</b>. Test: plasma free metanephrines or 24-hour urinary fractionated metanephrines. <b>Surgery: ALPHA blockade first, then beta</b> &mdash; isolated beta blockade is dangerous.","s":1},{"t":"Coarctation","d":"<b>Radial-femoral delay</b>; leg systolic <i>lower</i> than arm (<b>normally it is higher</b>). <b>Echocardiography</b> establishes it; refer to a vascular surgeon or structural cardiologist.","s":1},{"t":"Heart","d":"Left ventricular hypertrophy with impaired diastolic relaxation &mdash; <b>independently</b> raises risk. Progresses to heart failure with <b>either preserved OR reduced</b> ejection fraction, so <b>a normal ejection fraction does not reassure</b>.","s":2},{"t":"Brain","d":"<b>Both</b> ischemic stroke and intracerebral hemorrhage, plus small-vessel white matter change, lacunar infarcts and cognitive decline. <b>Acute stroke follows a distinct protocol &mdash; never apply chronic targets acutely.</b>","s":2},{"t":"Kidney","d":"Injury to vessels, glomeruli and interstitium. Earliest markers: <b>rising urine albumin-to-creatinine ratio, falling estimated filtration rate</b> &mdash; both read as <i>trends</i>.","s":2},{"t":"Aorta","d":"Dissection: abrupt severe chest/back/abdominal pain, <b>maximal at onset</b>, often tearing. Pulse deficits, asymmetric arm pressures, aortic regurgitation murmur, new neurological deficit. <b>Neither normal pulses NOR a normal chest radiograph excludes it.</b> Immediate cross-sectional vascular imaging; urgent surgery.","s":2},{"t":"Arteries","d":"Shear stress &rarr; intimal injury &rarr; low-density lipoprotein oxidation &rarr; smooth muscle proliferation. <b>Treat total cardiovascular risk, not pressure alone.</b>","s":2},{"t":"Retina","d":"Predicts long-term stroke risk <b>independently of the pressure level</b>; retinal arterial narrowing predicts future hypertension; <b>control can produce regression</b>. <b>Focal</b> narrowing, hemorrhages and exudates = <b>current</b> pressure. <b>Generalized</b> narrowing and AV nicking = <b>current AND previous</b>. Disc edema = emergency.","s":2},{"t":"Symptoms","d":"Most patients with mild to moderate primary hypertension have <b>no reliable blood pressure-related symptoms</b>. Headache is common but nonspecific and cannot guide anything.","s":3},{"t":"Immediate evaluation","d":"Confusion or seizures &middot; visual disturbance or focal deficit &middot; <b>abrupt severe</b> headache &middot; chest or severe back pain &middot; oliguria.","s":3},{"t":"Measurement technique","d":"Rest <b>&ge; 5 minutes</b>, empty bladder, no smoking/caffeine/vigorous activity for 30 minutes. Back supported, feet flat, <b>legs uncrossed</b>, bare arm at heart level, <b>not speaking</b>. Cuff matched to arm circumference. At least two readings. <b>Both arms initially &mdash; use the higher consistent arm at follow-up.</b>","s":3},{"t":"Why technique matters","d":"Measurement error is one of the first things to exclude before labeling a patient resistant &mdash; <b>bad technique mimics true resistance exactly</b>.","s":3},{"t":"Baseline panel","d":"Creatinine with filtration rate, <b>urine albumin-to-creatinine ratio</b>, electrolytes, glucose or glycated hemoglobin, lipids, thyroid-stimulating hormone, full blood count, urinalysis. Three jobs at once: screen secondary causes, measure organ damage, set a baseline before drugs that move potassium and creatinine.","s":3},{"t":"Electrocardiogram","d":"Voltage criteria for hypertrophy are <b>specific but NOT sensitive</b> &mdash; a normal tracing does <i>not</i> exclude hypertensive heart disease.","s":3},{"t":"Not routine","d":"<b>Chest radiograph</b> &mdash; only for suspected pulmonary edema, cardiomegaly, or widened mediastinum. <b>Echocardiography</b> &mdash; only for suspected heart failure, significant murmur, hypertrophy on ECG, or unexplained dyspnea.","s":3},{"t":"Home monitoring","d":"Validated upper-arm device. <b>Two readings a minute apart, morning and evening, seven days; report the average.</b> Educate: <b>do not overreact to the highest single reading.</b>","s":3},{"t":"Lifestyle","d":"Recommended at <b>every</b> blood pressure category, and continues alongside drugs. DASH-style with reduced sodium &middot; ~<b>150 min/week</b> moderate aerobic plus resistance training &middot; sustained <b>5&ndash;10 kg</b> loss meaningfully lowers systolic &middot; alcohol to low-risk thresholds (<b>never start alcohol for cardiovascular benefit</b>).","s":4},{"t":"First-line classes","d":"<b>Thiazide-type diuretic</b> (chlorthalidone preferred) &middot; <b>ACE inhibitor OR angiotensin receptor blocker</b> &middot; <b>dihydropyridine calcium channel blocker</b>. Beta blockers are deliberately absent.","s":4},{"t":"Thiazide","d":"Monitor electrolytes, uric acid, volume status. Hyponatremia &middot; hypokalemia &middot; <b>hyperuricemia may precipitate gout</b> &middot; volume depletion. <b>At 65+, check sodium</b> &mdash; especially women and low-normal sodium. With a beta blocker: higher new-onset diabetes risk.","s":4},{"t":"ACE inhibitor / ARB","d":"<b>Dry cough</b> (bradykinin-mediated, up to ~1 in 5 &rarr; switch to an ARB) &middot; hyperkalemia &middot; creatinine rise &middot; <b>angioedema</b>, <b>2&ndash;4&times; more common in Black patients</b>. <b>Avoid:</b> pregnancy, prior angioedema, bilateral renal artery stenosis.","s":4},{"t":"Dihydropyridine","d":"<b>Dependent ankle edema</b> is commonest &mdash; vasodilatory, so <i>a diuretic does not fix it</i>. Also flushing, headache, gingival enlargement.","s":4},{"t":"NEVER combine","d":"<b>ACE inhibitor + ARB</b> &mdash; hyperkalemia and acute kidney injury risk <i>with no added benefit</i>; one is used INSTEAD of the other. <b>Beta blocker + verapamil/diltiazem</b> &mdash; both slow the sinus and AV nodes &rarr; severe bradycardia and heart block. Non-dihydropyridines are also avoided where the ejection fraction is reduced.","s":4},{"t":"Beta blockers","d":"<b>NOT first-line</b> for uncomplicated hypertension. Preferred where the comorbidity selects them: <b>heart failure with reduced ejection fraction, recent myocardial infarction, ischemic disease</b>.","s":4},{"t":"Starting","d":"<b>Stage 1</b> &rarr; one first-line agent. <b>Stage 2</b> &rarr; two complementary agents, ideally a <b>single-pill combination</b> (adherence is itself a main determinant of control). <b>Preferred pairings:</b> a renin-angiotensin blocker with <i>either</i> a dihydropyridine <i>or</i> a thiazide-type diuretic.","s":4},{"t":"Exclude the impostors first","d":"<b>Nonadherence is the commonest cause</b> of apparent resistance. Then measurement error &middot; white coat effect &middot; high sodium or alcohol &middot; interfering drugs &middot; undiagnosed sleep apnea or secondary hypertension.","s":5},{"t":"Step 1","d":"<b>Optimize the diuretic</b> &mdash; chlorthalidone preferred, class matched to renal function. An inadequate diuretic is a common reason the other two agents appear to fail.","s":5},{"t":"Step 2","d":"Titrate the renin-angiotensin blocker and the dihydropyridine to maximally tolerated doses.","s":5},{"t":"Step 3","d":"Add <b>spironolactone</b> &mdash; the most evidence-supported fourth agent &mdash; if filtration rate and potassium allow.","s":5},{"t":"Step 4","d":"Escalate by physiology and comorbidity: beta blockade &middot; <b>hydralazine</b> (reflex tachycardia and fluid retention &rarr; needs combination therapy) &middot; <b>clonidine</b> (sedation, dry mouth, <b>rebound hypertension on abrupt withdrawal</b>). Then refer to a hypertension specialist.","s":5},{"t":"Emergency: how fast","d":"<b>Reduce mean arterial pressure by no more than ~20&ndash;25% in the first hour</b>, then toward ~160/100&ndash;110 over 2&ndash;6 hours, normalizing gradually over a day or two.","s":5},{"t":"Emergency: why not faster","d":"<b>Autoregulation has adapted to the higher pressure.</b> The organs reset the range over which they protect their own perfusion, so normalizing too fast leaves them underperfused at a value that would be safe in anyone else &mdash; causing ischemic stroke, myocardial injury or renal failure.","s":5},{"t":"Exceptions","d":"<b>Aortic dissection</b> and <b>some stroke syndromes</b> &mdash; acute stroke follows its own protocol.","s":5},{"t":"Hypotension","d":"A decrease in systemic pressure below normal. <b>Not a diagnosis</b> &mdash; syncope is the <i>result</i> of symptomatic hypotension; treat the <b>real diagnosis</b>. Norms change with age; consider comorbidities and <b>relative</b> hypotension; each reading is a snapshot.","s":6},{"t":"Syncope vs near-syncope","d":"Syncope = transient, self-limited loss of consciousness and postural tone, spontaneous recovery. Near-syncope = dizziness, lightheadedness, tunnel vision <i>without</i> losing consciousness.","s":6},{"t":"Acute vs chronic","d":"<b>Acute</b>: sudden, usually symptomatic, specific trigger (toxic or overdose; infection = <i>long-lasting</i> acute). <b>Chronic</b>: waxes and wanes, intermittently symptomatic, cause may be unavoidable (reduced ejection fraction heart failure, cardiomyopathy).","s":6},{"t":"Three syncope groups","d":"<b>Orthostatic</b> (neurogenic, non-neurogenic) &middot; <b>reflex</b> (situational, vasovagal) &middot; <b>cardiogenic</b> (arrhythmia, structural, vascular).","s":6},{"t":"Non-hypotensive syncope","d":"Hypoglycemia, seizure, toxic overdose, electrolyte imbalance, hypoxia, anxiety, anemia, postural tachycardia syndrome. Against seizure: no tongue biting, incontinence or prolonged confusion.","s":6},{"t":"&#9733; Orthostatic criteria","d":"Supine then standing. Systolic fall <b>&gt;20</b> or diastolic <b>&gt;10 mmHg within 3 minutes</b>; systolic <b>&gt;30</b> with elevated baseline or supine hypertension. One criterion is enough (spoken). <b>History is THE most important part.</b>","s":7},{"t":"&#9733; The big tell: heart rate","d":"Pressure falls in both. <b>Significant heart rate rise = non-neurogenic</b> (intact reflex; e.g. 68 &rarr; 92). <b>Minimal rise = neurogenic</b> (autonomic failure; e.g. 72 &rarr; 76).","s":7},{"t":"Neurogenic","d":"Autonomic failure: <b>diabetes, Parkinson disease, multiple system atrophy</b>. Volume depletion usually absent; autonomic symptoms often present. Clue: numb feet in long-standing diabetes.","s":7},{"t":"Non-neurogenic","d":"Hypovolemia, medication, <b>advanced age</b>: <b>diarrhea, hemorrhage, diuretics</b>. Volume depletion often present (dry mucous membranes); autonomic symptoms usually absent.","s":7},{"t":"Orthostatic treatment","d":"Slow positional changes; treat the underlying cause; iatrogenic &rarr; reduce or remove the drug.","s":7},{"t":"Vasovagal","d":"&ldquo;The common faint&rdquo;, most common type, <b>young women</b>. Triggers: emotional stress, fear, pain, heat, prolonged standing. Warm, nauseated, sweaty prodrome.","s":7},{"t":"Situational","d":"A bodily function or action: cough, sneeze, <b>micturition</b> (voiding standing at night; alcohol, dehydration, alpha-1 blocker with lisinopril).","s":7},{"t":"&#9733; Reflex diagnosis & care","d":"<b>History, history, history</b> + a <b>log</b> of pattern and frequency. <b>Trigger avoidance</b>; safety precautions during unavoidable triggers.","s":7},{"t":"Postural orthostatic tachycardia syndrome","d":"Heart rate rise <b>&gt;30 or above 120 within 10 minutes</b> (adolescents: <b>40</b>); improves lying down. Ages 15&ndash;50, women &gt; men, Ehlers-Danlos. <b>Tilt-table</b>: sensitivity 40% (negative tells little), specificity &gt;80%. Water + salt; fludrocortisone. (Deck: &ldquo;positional&rdquo;.)","s":8},{"t":"Cardiogenic","d":"Abrupt collapse <b>without warning</b>, palpitations, heart disease. Arrhythmia &rarr; electrocardiogram, monitor, stress test. Structural &rarr; echocardiogram, stress echo. Vascular &rarr; <b>emergent testing in the emergency department</b>. All: cardiology consultation.","s":8},{"t":"&#9733; Drug &harr; condition","d":"<b>Midodrine</b>: best with <b>neurogenic</b>; avoid with supine hypertension, severe heart disease, chronic kidney disease. <b>Fludrocortisone</b>: best with postural tachycardia syndrome; avoid in heart failure (salt and water retention). <b>Droxidopa</b>: mild, better with supine hypertension, adjunct.","s":8},{"t":"Pressors","d":"Epinephrine, norepinephrine, dopamine, phenylephrine, vasopressin: <b>emergency department and intensive care only</b>.","s":8},{"t":"&#9733; Education","d":"&ldquo;<b>Understanding is the key to compliance.</b>&rdquo; No dosing or mechanism questions.","s":8},{"t":"Memory aid: the garbage system","d":"<i>A story, not a fact.</i> <b>HDL (high-density lipoprotein) = garbage trucks</b> (apo A-I, never apo B): excess cholesterol back to the liver and bile. <b>LDL (low-density lipoprotein) = building-material trucks</b> (B-100), the highest risk &mdash; <b>clear them first</b>, then fuel if triglyceride is still &gt;200. <b>Chylomicrons = gut fuel barges</b> (B-48); <b>VLDL (very-low-density) = liver fuel tankers</b> (B-100) &rarr; IDL (intermediate-density) after drop-off. <b>Lp(a) = delivery truck with an armored trailer</b>. <b>LDL receptor = the liver&rsquo;s gate</b> (broken in familial hypercholesterolemia); <b>PCSK9 = the demolition crew</b>. <b>Apo E = tow ticket</b> for empty tankers.","s":9},{"t":"Lipoproteins","d":"Chylomicrons: least dense, after fatty food, triglyceride. VLDL: mainly triglyceride. LDL: mostly cholesterol, &ldquo;bad&rdquo;, <b>highest risk</b>, primary target. HDL: densest, reverse cholesterol transport, &ldquo;good&rdquo;, raised by exercise. Lp(a): LDL-like + apo(a), causal independent risk &rarr; aggressive LDL lowering.","s":9},{"t":"Apolipoproteins","d":"B-48 intestine (chylomicrons) &middot; B-100 liver (VLDL, IDL, LDL, Lp(a)) &middot; B absent from HDL &middot; A-I on all HDL &middot; E critical in triglyceride clearance (E2 homozygosity &rarr; dysbetalipoproteinemia).","s":9},{"t":"Lab bands (mg/dL)","d":"Total &lt;200 desirable, &gt;240 high &middot; LDL &lt;100 optimal, 160&ndash;189 high, &gt;190 very high &middot; HDL &lt;40 low, &gt;60 high &middot; Triglyceride &lt;150 normal, 200&ndash;499 high, &gt;500 very high.","s":9},{"t":"Exam findings","d":"Eruptive xanthomas (small yellow-white papules, back, buttocks, extensors) &rarr; very high triglyceride. Tendon xanthomas (Achilles, hands) &rarr; high LDL / familial hypercholesterolemia. Xanthelasma; corneal arcus before 40 &rarr; genetic.","s":9},{"t":"&#9733; Familial chylomicronemia","d":"Fasting triglyceride &gt;500, usually <b>&gt;1000</b>; <b>acute pancreatitis</b> (severe abdominal pain), eruptive xanthomas, <b>lipemia retinalis</b> (opalescent retinal vessels). &ldquo;One that can save somebody&rsquo;s life.&rdquo;","s":10},{"t":"Severe hypertriglyceridemia","d":"Triglyceride &gt;500, high total, low HDL, usually no LDL rise; risk = pancreatitis. Very low-fat diet (&lt;15%), weight, activity, <b>fibrate and/or niacin</b>. Take an alcohol history.","s":10},{"t":"&#9733; Homozygous familial hypercholesterolemia","d":"Two mutant LDL-receptor alleles; 1 in 1 million; <b>child</b> with xanthomas, total ~400 to &gt;1000, atherosclerosis before puberty. <b>Skin biopsy</b> (receptor activity) confirms. <b>LDL apheresis</b> = treatment of choice; add drugs; refractory &rarr; PCSK9 inhibitor.","s":10},{"t":"&#9733; Heterozygous familial hypercholesterolemia","d":"One allele; 1 in 250; <b>adult</b> with LDL 200&ndash;400, normal triglyceride, Achilles xanthomas (~75%), arcus, premature coronary disease in the family. <b>No definitive test.</b> High-intensity statin &rarr; ezetimibe &rarr; PCSK9 inhibitor if refractory (&ldquo;don&rsquo;t jump straight to the PCSK9&rdquo;).","s":10},{"t":"Other genetic types","d":"Familial defective apo B-100: familial-hypercholesterolemia picture, 1 in 1,500. Mixed: triglyceride &gt;150 + LDL &gt;130 (most common in practice). Dysbetalipoproteinemia: triglyceride and total <b>both 250&ndash;500</b>, palmar and tuberoeruptive xanthomas, apo E2.","s":10},{"t":"Low HDL","d":"&lt;40 (women &lt;50 for metabolic syndrome). Lifestyle first: stop smoking (+10%), weight loss, aerobic exercise (+5%), healthier fats. Rule out diabetes, smoking, obesity; anabolic steroids lower it.","s":10},{"t":"Metabolic syndrome","d":"Any 3: waist &gt;40 in men / &gt;35 in women; triglyceride &gt;150; HDL &lt;40 men / &lt;50 women; blood pressure &gt;130/&gt;85; fasting glucose &gt;110. Lifestyle first.","s":10},{"t":"Secondary causes","d":"Before a statin rule out: <b>LDL</b> &rarr; hypothyroidism, nephrotic syndrome, primary biliary cirrhosis, anorexia. <b>Triglyceride &ge;500</b> &rarr; diabetes, chronic kidney disease, alcoholism, pregnancy, hypothyroidism. <b>Low HDL</b> &rarr; diabetes, smoking, obesity.","s":10},{"t":"Screening","d":"All adults <b>&ge;20</b>. Children once at <b>9&ndash;11</b> (non-fasting), again in late adolescence; from 2 with a family history. Total cholesterol and HDL need no fast; triglyceride and calculated LDL need 9&ndash;12 hours.","s":10},{"t":"&#9733; LDL first, then triglyceride","d":"&ldquo;Address the LDLs, then address the triglycerides.&rdquo; If triglyceride stays &gt;200 after the LDL target, add triglyceride treatment. 200&ndash;499: intensify LDL drugs and/or add fibrate or niacin. Non-HDL = total &minus; HDL.","s":11},{"t":"&#9733; Drug &harr; lipid","d":"<b>Statin &rarr; LDL</b> (&darr;25&ndash;63%; monitor lipids, liver function, creatine kinase). <b>Fibrate &rarr; triglyceride</b>. <b>Niacin &rarr; raises HDL best</b>. <b>Ezetimibe, bile acid sequestrant &rarr; add-on LDL</b>. <b>PCSK9 inhibitor</b> (evolocumab, alirocumab) &rarr; refractory familial hypercholesterolemia / very high risk after statin + ezetimibe. Generic names only.","s":11},{"t":"Statin intensity","d":"By LDL fall, never milligrams: high &ge;50%, moderate 30&ndash;49%, low &lt;30%.","s":11},{"t":"&#9733; 2018 risk categories","d":"10-year risk &lt;5% low (lifestyle) &middot; 5&ndash;7.5% borderline (moderate statin if enhancers) &middot; 7.5&ndash;20% intermediate (moderate, &darr;30&ndash;49%) &middot; &ge;20% high (&darr;&ge;50%). Age 40&ndash;75, LDL 70&ndash;189, no diabetes.","s":11},{"t":"&#9733; 2018 statin groups","d":"Clinical ASCVD (atherosclerotic cardiovascular disease) &le;75 &rarr; high intensity. LDL &ge;190 &rarr; high intensity, no risk calculation. Diabetes 40&ndash;75 &rarr; moderate. Very high risk, LDL &ge;70 on max statin &rarr; add ezetimibe, then PCSK9 inhibitor. Uncertain &rarr; coronary artery calcium (0 may defer; &ge;100 statin).","s":11},{"t":"Lifestyle","d":"Saturated fat <b>&lt;7%</b> (slide wins over the spoken 10%), soluble fiber 20&ndash;30 g, plant stanols, lose 5&ndash;10%, 30 minutes activity, stop smoking. <b>2026 / PREVENT: rotations only, not tested.</b>","s":11},{"t":"&#9733; The words","d":"<b>Harsh / rumble = stenosis</b> &rarr; abnormal forward flow &rarr; pressure overload. <b>Blowing = regurgitation</b> &rarr; abnormal backflow &rarr; volume overload. No audio on the test &mdash; murmurs come as words.","s":12},{"t":"&#9733; Timing","d":"<b>Systolic</b>: aortic stenosis, mitral regurgitation, pulmonic stenosis, tricuspid regurgitation. <b>Diastolic</b>: aortic regurgitation, mitral stenosis, pulmonic regurgitation, tricuspid stenosis &mdash; &ldquo;ARMS rest because they are PRetty TiredS&rdquo;.","s":12},{"t":"&#9733; Where (A-P-E-T-M)","d":"<b>Aortic</b> 2nd right intercostal space, sternal border &middot; <b>Pulmonic</b> 2nd left &middot; <b>Erb&rsquo;s point</b> 3rd left &middot; <b>Tricuspid</b> 5th, lower left sternal border &middot; <b>Mitral</b> apex, 5th space, midclavicular line. Stems give the location, not the valve name.","s":12},{"t":"Respiration (RILE)","d":"<b>Right-sided louder on inspiration</b> (more venous return) &middot; <b>left-sided louder on expiration</b>. Carvallo sign = the inspiratory increase; it tells tricuspid from mitral regurgitation.","s":12},{"t":"Heart sounds","d":"S1 = mitral + tricuspid closing &middot; S2 = aortic + pulmonic closing &middot; S3 = dilated, volume-loaded ventricle (systolic failure) &middot; S4 = hypertrophied, pressure-loaded ventricle (diastolic failure, e.g. aortic stenosis).","s":12},{"t":"Equal weight","d":"&ldquo;Just as likely a tricuspid valve question as an aortic valve question.&rdquo; Grading is tested only for aortic and mitral stenosis, plus <b>severe regurgitation = regurgitant fraction &ge;50%</b>.","s":12},{"t":"&#9733; Aortic stenosis","d":"Most common valve disease. &gt;70 degenerative, &lt;70 <b>bicuspid</b>. <b>Harsh systolic crescendo-decrescendo, 2nd right space, to the carotids</b>; softer with Valsalva, standing, handgrip; louder squatting, sitting forward. Forceful apex + <b>delayed, weak carotid = severe</b>.","s":13},{"t":"&#9733; Aortic stenosis numbers","d":"Severe = <b>area &lt;1.0 cm&sup2;, mean gradient &gt;40 mmHg, jet &gt;4.0 m/s</b> (&ldquo;4, 40 and 1&rdquo;). Survival: angina 5 y &middot; syncope 3 y &middot; <b>heart failure 2 y (most common, worst)</b>. Symptomatic: <b>75% dead at 3 years</b>.","s":13},{"t":"&#9733; Aortic stenosis care","d":"<b>Preload dependent</b>: avoid strenuous activity / competitive sports, dehydration; hypertension &rarr; avoid beta blockers and calcium channel blockers; angina &rarr; <b>avoid nitrates</b>. Surgery: severe + symptomatic systolic dysfunction, or bicuspid &rarr; transcatheter replacement; children / young adults &rarr; balloon valvuloplasty. <b>All on echo &rarr; cardiology.</b>","s":13},{"t":"&#9733; Aortic regurgitation","d":"<b>High-pitched blowing DIASTOLIC</b>, 3rd space / left upper sternal border, to the apex (the slide&rsquo;s &ldquo;holosystolic&rdquo; is struck). <b>Corrigan pulse</b> (water hammer: rapid upstroke, rapid collapse), de Musset (head bobbing), wide pulse pressure. Root causes: Marfan, dissection, aortitis, hypertension.","s":13},{"t":"Aortic regurgitation care","d":"Echo finds the <b>cause</b> (root dilation, dissection). Chronic, preserved fraction &rarr; <b>afterload reduction</b>. <b>Acute severe &rarr; emergency replacement (&lt;24 h)</b>; if delayed, IV diuretics + nitroprusside. Falling fraction &rarr; surgery; untreated survival 2&ndash;3 y. Audible murmur &rarr; cardiology.","s":13},{"t":"&#9733; Mitral stenosis","d":"<b>Rheumatic</b> (most common; 80% women; ~20 y after the fever). <b>Left atrium enlarges &rarr; atrial fibrillation &rarr; thromboembolism.</b> Hemoptysis, hoarseness (Ortner), dysphagia. <b>Low diastolic rumble at the apex after an opening snap</b>, bell, left side. Severe = <b>&lt;1.0 cm&sup2;, gradient &gt;10, velocity &gt;3.0</b>. Loop diuretic &rarr; balloon valvotomy.","s":13},{"t":"Mitral regurgitation","d":"Backflow into the left atrium in systole. Acute: papillary muscle / chordae rupture, endocarditis. <b>Holosystolic blowing at the apex &rarr; axilla</b>; louder squatting, handgrip; softer standing, Valsalva. Severe = <b>regurgitant fraction &ge;50%</b>. Surgery: ejection fraction &lt;60% or end-systolic dimension &gt;40 mm &rarr; clip, transcatheter or surgical replacement.","s":13},{"t":"Mitral valve prolapse","d":"Myxomatous; <b>healthy women 15&ndash;30</b>; <b>mid-systolic click at the apex</b>; echo: redundant leaflets &gt;5 mm. Usually benign, no treatment; may progress to mitral regurgitation.","s":13},{"t":"Pulmonic stenosis","d":"Almost always congenital (tetralogy of Fallot; carcinoid). <b>Harsh mid-systolic ejection, left upper sternal border, louder on inspiration</b>, split S2. Electrocardiogram: right axis deviation, right ventricular hypertrophy. Mild&ndash;moderate: none, 94% 20-y survival. Severe: diuretics + <b>balloon valvuloplasty</b>. On echo &rarr; cardiology.","s":14},{"t":"&#9733; Pulmonic regurgitation","d":"<b>Iatrogenic = most common</b> (after valvotomy / valvuloplasty for outflow obstruction); pulmonary hypertension = the high-pressure cause. <b>Graham Steell</b>: brief early diastolic decrescendo, 2nd left space. Usually incidental. Treat the cause; refer on echo or right heart failure.","s":14},{"t":"Tricuspid stenosis","d":"Rheumatic worldwide, congenital in the US; women. Right atrium &rarr; right ventricle blocked. <b>Mid-diastolic rumble near the xiphoid, louder on inspiration</b>; right upper quadrant pain, cold skin. Electrocardiogram: right atrial enlargement out of proportion. Low salt, diuretics, aldosterone antagonist; <b>bioprosthetic</b> replacement. (Suffusion sign not tested.)","s":14},{"t":"&#9733; Tricuspid regurgitation","d":"Most common = <b>annular dilation from pulmonary hypertension</b>; primary = <b>endocarditis in intravenous drug users</b>. <b>Holosystolic, lower left sternal border, louder on inspiration (Carvallo)</b> &mdash; that separates it from mitral regurgitation. Raised jugular pressure, venous thrill; severe: edema, ascites. Annuloplasty.","s":14},{"t":"&#9733; Mechanical valve","d":"Titanium and carbon &rarr; <b>lifelong vitamin K antagonist (warfarin)</b> &mdash; over no therapy and over antiplatelets. International normalized ratio: <b>aortic 2.5</b> (2.0&ndash;3.0) &middot; <b>mitral 3.0</b> (2.5&ndash;3.5) &middot; <b>both 3.0</b>. Surgery &rarr; <b>bridge with heparin</b>.","s":14},{"t":"Biological valve","d":"Pig or cow tissue &rarr; no anticoagulation beyond the immediate postoperative period; preferred when anticoagulation is contraindicated. (Valve type by age on slide 74 is unsettled &mdash; not learned.)","s":14},{"t":"2022, not the deck","d":"Tested on the <b>2022</b> guideline; slide 57 (2026 changes) = rotations only. Learn <b>&ldquo;mildly&rdquo;</b> reduced (not &ldquo;moderately&rdquo;), <b>&le;40 / 41&ndash;49 / &ge;50</b> (not &lt;40 / &gt;50), stage D = <b>advanced</b> (not &ldquo;decompensated&rdquo;), calcium channel blockers = <b>avoid</b> (no subclass ranking), beta blockers by <b>class</b>. Digitalis not keyed.","s":15},{"t":"&#9733; Systolic vs diastolic","d":"<b>Systolic</b> = squeeze fails: ischemic or dilated cardiomyopathy &rarr; reduced ejection fraction &rarr; normal or low pressure &rarr; <b>third heart sound</b> &rarr; pulmonary edema. <b>Diastolic</b> = relaxation fails: hypertrophic (hypertension) &rarr; preserved fraction &rarr; hypertension &rarr; <b>fourth heart sound</b> &rarr; peripheral then pulmonary edema. Add an elevated B-type natriuretic peptide = slam dunk.","s":15},{"t":"&#9733; Normal values","d":"Cardiac output <b>5&ndash;6 L/min</b>. Normal ejection fraction <b>&ge;50%</b> &mdash; the treatment line is 50 and above vs 49 and below.","s":15},{"t":"Reduced","d":"Ejection fraction <b>&le;40%</b>.","s":15},{"t":"Mildly reduced","d":"<b>41&ndash;49%</b>, never previously &le;40%.","s":15},{"t":"Preserved","d":"<b>&ge;50%</b>.","s":15},{"t":"Improved","d":"Was &le;40%, now &gt;40% &mdash; history decides the label (30% &rarr; 46% is improved, not mildly reduced).","s":15},{"t":"New York Heart Association class","d":"I no symptoms &middot; II symptoms with exertion &middot; III with slight exertion &middot; IV at rest. A grade of symptoms.","s":15},{"t":"Stages A&ndash;D (natural history)","d":"<b>A</b> at risk, normal heart &middot; <b>B</b> pre-heart failure: structural disease, no symptoms (asymptomatic left ventricular hypertrophy = <b>B</b>, not A) &middot; <b>C</b> symptomatic, past or current &middot; <b>D</b> advanced. Never moves backward.","s":15},{"t":"&#9733; Stage A / B therapy","d":"<b>Stage A with diabetes &rarr; sodium-glucose cotransporter 2 inhibitor, NOT a beta blocker</b> (&ldquo;it&rsquo;ll be on your test&rdquo;). Stage B adds ACE (angiotensin-converting enzyme) inhibitor (receptor blocker if intolerant) and beta blocker.","s":15},{"t":"&#9733; Clinical diagnosis","d":"Signs and symptoms + an <b>elevated B-type natriuretic peptide</b> or <b>objective congestion</b>. &ldquo;Clinical diagnosis requires congestion; congestion = edema.&rdquo;","s":16},{"t":"&#9733; Natriuretic peptide cut-offs","d":"<b>BNP (B-type natriuretic peptide)</b>: &lt;100 rules out acute failure; 100&ndash;400 gray zone; &gt;400 likely; <b>&gt;900 likely acute</b>. <b>NT-proBNP (N-terminal pro-B-type)</b>: &lt;300 rules out; &gt;125 likely if &lt;75 years, <b>&gt;450 if &gt;75</b>. BNP is degraded by neprilysin, so sacubitril-valsartan alters it.","s":16},{"t":"Which test answers what","d":"Echocardiogram: structures, ejection fraction group, definitive for right-sided. Multigated acquisition scan: most accurate ejection fraction. Chest radiograph: effusion, cephalization, Kerley B lines, big heart. Metabolic panel: potassium, renal function. Troponin only if ischemia is suspected.","s":16},{"t":"Left vs right","d":"<b>Left</b> = 70&ndash;80%, pulmonary congestion, orthopnea, paroxysmal nocturnal dyspnea. <b>Right</b> = edema, jugular venous distension, hepatomegaly; most often from <b>chronic left failure</b> (also mitral stenosis, pulmonary arterial hypertension); worse prognosis.","s":16},{"t":"&#9733; Reduced fraction therapy (all strong)","d":"Angiotensin receptor-neprilysin inhibitor (class II&ndash;III) or ACE inhibitor / receptor blocker (II&ndash;IV) + <b>beta blocker</b> + <b>mineralocorticoid receptor antagonist</b> + <b>sodium-glucose cotransporter 2 inhibitor</b> + diuretics as needed. Hydralazine + isosorbide dinitrate for African American patients, class III&ndash;IV.","s":16},{"t":"Mildly reduced &amp; preserved","d":"Diuretics as needed (strong); sodium-glucose cotransporter 2 inhibitor (moderate); the rest weak. &ldquo;Very similar&rdquo; to each other; different from reduced.","s":16},{"t":"Avoid","d":"<b>Calcium channel blockers.</b> Inotropes (dobutamine, milrinone) = <b>intensive care only</b>.","s":16},{"t":"Defibrillator","d":"Ejection fraction <b>&le;35%</b>, class II&ndash;III, on optimal therapy, life expectancy <b>&ge;1 year</b> (the slide wins over the spoken &ldquo;under a year&rdquo;). After an acute event with fraction &lt;35%: wearable vest &rarr; optimize + rehab &rarr; recheck echo.","s":16},{"t":"High-output","d":"Raised output from demand: anemia, hyperthyroidism, arteriovenous fistula (also obesity, chronic lung disease, cirrhosis, Paget disease). Treat the cause; diuretic.","s":16}],"map":{"clinical-medicine-and-surgery-i-exam-4-atherosclerosis-lipids-quiz-version-2":[-1,81,66,79,-1,81,67,78,67,-1,82,7,81,7,78,72,69,69,82,-1,71,67,66,-1,73,70,-1,7,77,-1],"clinical-medicine-and-surgery-i-exam-4-atherosclerosis-lipids-quiz":[72,-1,-1,70,-1,66,77,-1,-1,66,78,84,66,-1,-1,-1,-1,-1,84,-1,108,74,-1,-1,73,72,71,81,75,-1],"clinical-medicine-and-surgery-i-exam-4-atherosclerosis-lipids-vignettes-version-2":[-1,72,-1,66,-1,73,74,-1,66,72,84,72,-1,79,-1,-1,82,74,82,81,72,74,-1,72,74,66,82,77,-1,74],"clinical-medicine-and-surgery-i-exam-4-atherosclerosis-lipids-vignettes":[-1,-1,84,77,74,79,-1,-1,74,81,82,82,81,72,75,74,84,-1,82,-1,82,79,71,72,7,73,72,82,85,-1],"clinical-medicine-and-surgery-i-exam-4-heart-failure-quiz-version-2":[123,121,109,7,115,50,115,113,119,115,124,117,116,7,28,6,119,50,120,120,-1,-1,124,115,103,117,-1,113,107,109],"clinical-medicine-and-surgery-i-exam-4-heart-failure-quiz":[116,50,116,117,116,115,107,-1,109,116,121,124,116,107,109,-1,124,-1,-1,-1,122,120,-1,-1,113,117,115,7,119,65],"clinical-medicine-and-surgery-i-exam-4-heart-failure-vignettes-version-2":[122,109,124,-1,116,117,117,117,49,121,120,115,123,107,115,119,118,123,119,109,116,123,-1,121,-1,119,117,124,7,115],"clinical-medicine-and-surgery-i-exam-4-heart-failure-vignettes":[119,116,109,120,109,113,121,122,115,117,107,123,117,124,115,121,123,116,117,65,115,116,28,119,109,65,117,107,119,-1],"clinical-medicine-and-surgery-i-exam-4-hypertension-quiz-version-2":[16,-1,23,-1,-1,-1,7,-1,29,8,37,-1,25,6,16,26,17,5,0,18,10,34,16,24,9,30,38,11,-1,17],"clinical-medicine-and-surgery-i-exam-4-hypertension-quiz":[17,32,-1,-1,11,32,35,15,45,19,43,39,31,3,10,30,12,26,4,13,12,7,36,4,-1,35,18,27,22,33],"clinical-medicine-and-surgery-i-exam-4-hypertension-vignettes-version-2":[13,33,9,-1,116,9,14,15,5,17,12,12,10,43,28,-1,39,11,41,30,16,38,5,36,19,25,31,4,-1,17],"clinical-medicine-and-surgery-i-exam-4-hypertension-vignettes":[20,42,29,40,24,23,0,26,45,50,34,18,21,23,32,26,33,37,11,24,39,30,8,31,34,10,22,10,32,46],"clinical-medicine-and-surgery-i-exam-4-hypotension-quiz-version-2":[48,60,62,48,48,48,59,57,49,48,50,61,52,48,63,62,49,62,58,61,48,48,48,63,48,48,48,48,63,48],"clinical-medicine-and-surgery-i-exam-4-hypotension-quiz":[50,48,61,58,58,60,48,49,48,62,48,53,-1,61,56,53,49,49,55,62,64,63,56,51,63,57,48,48,52,48],"clinical-medicine-and-surgery-i-exam-4-hypotension-vignettes-version-2":[48,61,49,62,54,48,61,48,54,48,58,48,48,63,53,60,77,62,48,48,53,48,62,61,48,48,57,48,57,60],"clinical-medicine-and-surgery-i-exam-4-hypotension-vignettes":[59,58,48,64,48,52,53,62,62,48,50,48,59,63,48,48,48,29,61,61,48,48,48,48,48,54,-1,48,62,48],"clinical-medicine-and-surgery-i-exam-4-valvular-heart-disease-quiz-version-2":[95,98,-1,99,100,104,102,102,90,101,-1,96,101,100,97,99,93,99,103,103,88,94,101,97,104,104,97,99,97,103],"clinical-medicine-and-surgery-i-exam-4-valvular-heart-disease-quiz":[119,100,101,104,97,-1,97,103,99,92,103,104,105,100,99,102,92,101,93,98,96,96,98,94,86,103,102,103,105,97],"clinical-medicine-and-surgery-i-exam-4-valvular-heart-disease-vignettes-version-2":[99,100,100,98,103,98,103,97,99,101,104,96,98,94,94,104,103,102,96,97,-1,98,101,103,94,109,102,93,97,102],"clinical-medicine-and-surgery-i-exam-4-valvular-heart-disease-vignettes":[104,99,101,97,97,100,100,104,104,87,103,99,105,96,102,97,98,104,101,100,96,100,101,93,98,92,92,103,98,97]}};
